<script>
(() => {
    const refreshBindStatus = async () => {
        try {
            const response = await fetch('{{ route('admin.monitoring.live') }}', {headers: {'Accept': 'application/json'}, cache: 'no-store'});
            if (!response.ok) return;
            const data = await response.json();
            (data.accounts || []).forEach(account => {
                const status = document.getElementById('bind-status-' + account.user_id);
                const count = document.getElementById('bind-count-' + account.user_id);
                if (status) status.innerHTML = `<span class="tag">${account.enabled ? 'ENABLED' : 'DISABLED'}</span>`;
                if (count) count.innerHTML = `<strong>${Number(account.current_binds || 0)} / ${Number(account.max_bind || 0)}</strong>`;
            });
        } catch (error) {
            // Keep the last known values visible when Jasmin is temporarily unavailable.
        }
    };
    refreshBindStatus();
    setInterval(refreshBindStatus, 5000);
})();
</script>
